import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _safe_get(dct: Any, *keys: str) -> Any:
    cur = dct
    for key in keys:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(key)
    return cur


def _to_str(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, (str, int, float, bool)):
        return str(value)
    if isinstance(value, dict):
        for k in ("value", "text", "content", "RawValue"):
            if k in value and value[k] is not None:
                return _to_str(value[k])
    return None


def _extract_label_value(item: Dict[str, Any], label_name: str) -> Optional[str]:
    for field in ("LabelDetection", "ValueDetection"):
        if field in item and isinstance(item[field], dict):
            text = item[field].get("Text")
            if text:
                return str(text)
    return None


def _normalize_currency(amount: Optional[str]) -> Optional[str]:
    if amount is None:
        return None
    text = str(amount).strip()
    if not text:
        return None
    return text.replace(",", "")


def _normalize_date(text: Optional[str]) -> Optional[str]:
    if text is None:
        return None
    return str(text).strip() or None


def _normalize_expense_response(textract_response: Dict[str, Any]) -> Dict[str, Any]:
    document_currency = None
    expense_date = None
    vendor_name = None
    invoice_id = None
    subtotal = None
    tax = None
    tip = None
    total = None
    line_items: List[Dict[str, Any]] = []

    expense_docs = textract_response.get("ExpenseDocuments", []) or []
    if expense_docs:
        expense_doc = expense_docs[0]
        summary_fields = expense_doc.get("SummaryFields", []) or []
        for field in summary_fields:
            ftype = _to_str(field.get("Type", {}).get("Text"))
            value = _to_str(field.get("ValueDetection", {}).get("Text"))
            group = _to_str(field.get("GroupProperties", [{}])[0].get("Types", [None])[0]) if field.get("GroupProperties") else None

            if not ftype:
                continue
            key = ftype.upper()

            if key in {"INVOICE_RECEIPT_DATE", "TRANSACTION_DATE", "DATE"} and expense_date is None:
                expense_date = _normalize_date(value)
            elif key in {"VENDOR_NAME", "SUPPLIER_NAME"} and vendor_name is None:
                vendor_name = value
            elif key in {"INVOICE_RECEIPT_ID", "INVOICE_ID", "RECEIPT_ID"} and invoice_id is None:
                invoice_id = value
            elif key in {"TOTAL", "AMOUNT_DUE", "AMOUNT_PAID"} and total is None:
                total = _normalize_currency(value)
            elif key in {"SUBTOTAL"} and subtotal is None:
                subtotal = _normalize_currency(value)
            elif key in {"TAX", "SALES_TAX"} and tax is None:
                tax = _normalize_currency(value)
            elif key in {"TIP"} and tip is None:
                tip = _normalize_currency(value)
            elif key in {"CURRENCY"} and document_currency is None:
                document_currency = value

        linegroups = expense_doc.get("LineItemGroups", []) or []
        for group in linegroups:
            for item in group.get("LineItems", []) or []:
                fields = item.get("LineItemExpenseFields", []) or []
                normalized_item: Dict[str, Any] = {}
                for fld in fields:
                    ftype = _to_str(fld.get("Type", {}).get("Text"))
                    val = _to_str(fld.get("ValueDetection", {}).get("Text"))
                    if not ftype or val is None:
                        continue
                    k = ftype.lower()
                    if k in {"item", "description", "product_code", "sku"}:
                        normalized_item[k] = val
                    elif k in {"quantity", "unit_price", "price", "amount"}:
                        normalized_item[k] = _normalize_currency(val)
                    elif k in {"currency"}:
                        normalized_item[k] = val
                if normalized_item:
                    line_items.append(normalized_item)

    normalized = {
        "vendor_name": vendor_name,
        "invoice_id": invoice_id,
        "invoice_date": expense_date,
        "currency": document_currency,
        "subtotal": subtotal,
        "tax": tax,
        "tip": tip,
        "total": total,
        "line_items": line_items,
        "raw_provider": "amazon-textract",
    }
    return normalized


def normalize_expense_fields(document_bytes: bytes, mime_type: str = "application/pdf", region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema using Amazon Textract AnalyzeExpense.
    Returns a dictionary ready for JSON serialization.
    """
    client = boto3.client("textract", region_name=region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION"))
    try:
        response = client.analyze_expense(
            Document={
                "Bytes": document_bytes,
            }
        )
    except (ClientError, BotoCoreError) as exc:
        raise RuntimeError(f"Textract AnalyzeExpense failed: {exc}") from exc

    return _normalize_expense_response(response)


def normalize_expense_fields_from_base64(
    document_base64: str,
    mime_type: str = "application/pdf",
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    document_bytes = base64.b64decode(document_base64)
    return normalize_expense_fields(document_bytes=document_bytes, mime_type=mime_type, region_name=region_name)


def normalize_expense_fields_to_json(document_bytes: bytes, mime_type: str = "application/pdf", region_name: Optional[str] = None) -> str:
    return json.dumps(normalize_expense_fields(document_bytes=document_bytes, mime_type=mime_type, region_name=region_name), ensure_ascii=False)
